#!/usr/bin/env python3
"""Exercise native windows with deterministic old-format reports and real Qt input events."""
import argparse
import json
import os
from pathlib import Path
import subprocess
import sys


def main():
    parser=argparse.ArgumentParser();parser.add_argument('--exe',type=Path,required=True);parser.add_argument('--output',type=Path,required=True);parser.add_argument('--fixtures',type=Path,required=True);parser.add_argument('--hdc',type=Path);args=parser.parse_args()
    output=args.output.resolve();output.mkdir(parents=True,exist_ok=True);fixtures=args.fixtures.resolve()
    profile=output/'profile';profile.mkdir(exist_ok=True)
    settings={'sessionsDir':str(fixtures),'hdcPath':str(args.hdc.resolve()) if args.hdc else ''}
    (profile/'settings.json').write_text(json.dumps(settings),encoding='utf-8')
    report=lambda name:json.dumps(str(fixtures/name))
    steps=[]
    def add(name,**kwargs):steps.append(dict(name=name,**kwargs))
    add('main window',delay=700,eval='qa.nativePointer=true;root.raise();root.requestActivate();qa.hover(root.bodyItem,2,2)',wait='root.active',screenshot='main.png')
    for page in ['watch','peak','snap','reports','settings']:
        add('navigate '+page,eval=f'root.go({json.dumps(page)})')
        add('render '+page,delay=160,screenshot=page+'.png')
    add('open trend',eval='backend.openReport('+report('Trend-1')+')',wait='root.childWindows.length===1')
    add('prepare trend capture',eval='var report=root.childWindows[0];report.raise();report.requestActivate();var plot=qa.find(report,"memoryPlot");qa.hover(report.bodyItem,2,2);')
    add('trend layout',delay=300,wait='report.active',assert_='plot.width>300 && plot.height>200 && qa.find(report,"statCards").height===86',window='report',screenshot='trend.png')
    add('zoom native chart',eval='qa.wheel(plot,plot.width/2,plot.height/2,400)',assert_='plot.rangeEnd-plot.rangeStart<plot.totalSpan')
    add('hover sample',eval='qa.hover(plot,plot.width*.6,plot.height*.5)',wait='plot.tooltip.items && plot.tooltip.items.length===14',window='report',screenshot='tooltip.png')
    add('enter tooltip',eval='var tip=qa.find(report,"chartTip");qa.hover(tip.contentItem,40,30)')
    add('tooltip remains enterable',delay=500,assert_='tip.visible && tip.retained.items.length===14')
    add('leave tooltip',eval='qa.hover(report.bodyItem,2,2)')
    add('tooltip dismissed',wait='!tip.visible',timeout=2500)
    add('expand chart',eval='qa.click(qa.find(report,"maximizeChart"),-1,-1)',wait='qa.find(report,"expandedChart").opened')
    add('expanded screenshot',delay=200,window='report',screenshot='chart-expanded.png')
    add('restore expanded chart',eval='qa.key(report,16777216)',wait='!qa.find(report,"expandedChart").opened')
    add('reset chart',eval='plot.resetView();qa.hover(plot,0,0)',assert_='plot.rangeStart===0 && plot.rangeEnd===plot.totalSpan')
    add('rename report',eval='backend.renameReport('+report('Trend-1')+',"Trend-1 重命名");',wait='report.meta.taskName==="Trend-1 重命名"')
    add('restore name',eval='backend.renameReport('+report('Trend-1')+',"Trend-1")',wait='report.meta.taskName==="Trend-1"')
    add('open snapshot',eval='backend.openReport('+report('Snapshot-1')+')',wait='root.childWindows.length===2')
    add('snapshot',delay=200,window='root.childWindows[1]',screenshot='snapshot.png')
    paths=[str(fixtures/f'Trend-{i}') for i in range(1,5)]
    add('open four-report comparison',eval='backend.openCompare('+json.dumps(paths)+')',wait='root.childWindows.length===3')
    add('prepare comparison capture',eval='var compare=root.childWindows[2];var comparisonPlot=qa.find(compare,"memoryPlot");qa.hover(compare.bodyItem,2,2)')
    add('overlay layout',delay=300,assert_='comparisonPlot.width>300 && comparisonPlot.height>150',window='compare',screenshot='compare-overlay.png')
    add('compact comparison',eval='var comparisonWidth=compare.width;var comparisonHeight=compare.height;compare.width=1024;compare.height=684')
    add('compact comparison keeps chart readable',delay=300,assert_='comparisonPlot.width>300 && comparisonPlot.height>150',window='compare',screenshot='compare-compact.png')
    add('restore comparison size',eval='compare.width=comparisonWidth;compare.height=comparisonHeight')
    add('peak alignment',eval='compare.alignment="peak";compare.metric="GL";',assert_='comparisonPlot.alignment==="peak" && comparisonPlot.metric==="GL"')
    add('end alignment',eval='compare.alignment="end";',assert_='comparisonPlot.totalSpan>=359')
    add('open baseline picker',eval='var picker=qa.find(compare,"baselinePicker");qa.click(picker,-1,-1)',wait='picker.popup.opened')
    add('choose baseline C',eval='qa.key(compare,16777237);qa.key(compare,16777237);qa.key(compare,16777220)',wait='compare.baselineIndex===2')
    add('change baseline',eval='var originalOrder=compare.ordered.map(r=>r.meta.id).join();var originalColors=compare.ordered.map(r=>r.compareColor).join();var originalPicks=JSON.stringify(compare.picked);var start=comparisonPlot.rangeStart;var end=comparisonPlot.rangeEnd;compare.baselineIndex=0;compare.baselineIndex=2',assert_='compare.baseline.meta.id==="Trend-3" && compare.ordered.map(r=>r.meta.id).join()===originalOrder && compare.ordered.map(r=>r.compareColor).join()===originalColors && JSON.stringify(compare.picked)===originalPicks && comparisonPlot.rangeStart===start && comparisonPlot.rangeEnd===end',window='compare',screenshot='compare-baseline-c.png')
    add('picked mode',eval='compare.tab=1')
    add('select a sample',delay=200,eval='var mini=qa.find(compare,"memoryPlot");qa.click(mini,mini.width*.35,mini.height*.4)',assert_='compare.selected(compare.ordered[0])!==123',window='compare')
    add('clear picked hover',eval='qa.hover(mini,0,0);qa.hover(compare.bodyItem,2,2)')
    add('picked screenshot',delay=300,wait='!qa.find(compare,"chartTip").visible',window='compare',screenshot='compare-picked.png')
    add('edit sample number',eval='var sampleInput=qa.find(compare,"sampleIndex-0");qa.click(sampleInput,-1,-1);sampleInput.remove(0,sampleInput.length);sampleInput.insert(0,"20");qa.key(compare,16777220)',assert_='compare.selected(compare.ordered[0])===19')
    add('difference scroll keeps category fixed',eval='var differences=qa.find(compare,"differenceTable");var differenceScroll=qa.find(differences,"tableScroll");differenceScroll.contentX=200',assert_='Math.abs(qa.find(differences,"header-name").mapToItem(differences,0,0).x)<1 && differences.columns.length===5')
    add('reach fourth report',eval='var miniScroll=qa.find(compare,"miniScroll");miniScroll.contentItem.contentY=miniScroll.contentItem.contentHeight-miniScroll.availableHeight;qa.hover(compare.bodyItem,2,2)')
    add('fourth report screenshot',delay=300,window='compare',screenshot='compare-fourth-report.png')
    add('hide baseline without changing calculations',eval='var differencesBefore=JSON.stringify(compare.differenceRows);qa.click(qa.find(compare,"reportVisible-2"),-1,-1)',assert_='compare.hiddenReports.indexOf(compare.baseline.meta.sessionDir)>=0 && JSON.stringify(compare.differenceRows)===differencesBefore && compare.baselineIndex===2')
    add('restore baseline visibility',eval='qa.click(qa.find(compare,"reportVisible-2"),-1,-1)',assert_='compare.hiddenReports.length===0')
    add('snapshot comparison',eval='backend.openCompare('+json.dumps([str(fixtures/'Snapshot-1'),str(fixtures/'Snapshot-2')])+')',wait='root.childWindows.length===4')
    add('snapshot difference',delay=200,assert_='root.childWindows[3].differenceRows.length===14',window='root.childWindows[3]',screenshot='compare-snapshot.png')
    add('switch snapshot chart',eval='var snapshotWindow=root.childWindows[1];qa.click(qa.find(snapshotWindow,"pieChartButton"),-1,-1)',assert_='qa.find(snapshotWindow,"snapshotBody").chartMode==="pie"')
    add('snapshot donut screenshot',delay=300,window='snapshotWindow',screenshot='snapshot-donut.png')
    add('switch snapshot detail tab',eval='var snapBody=qa.find(snapshotWindow,"snapshotBody");qa.click(qa.find(snapBody,"detailTab-ashmem"),-1,-1)',assert_='snapBody.detailIndex===1')
    add('snapshot detail screenshot',delay=300,window='snapshotWindow',screenshot='snapshot-detail.png')
    add('activate independent window',eval='var closingWindow=root.childWindows[1];closingWindow.raise();closingWindow.requestActivate()',wait='closingWindow.active')
    add('minimize independent window shortcut',eval='qa.key(closingWindow,77,67108864)',wait='closingWindow.visibility===3')
    add('restore independent window',eval='closingWindow.showNormal();closingWindow.raise();closingWindow.requestActivate()',wait='closingWindow.active')
    add('independent window close shortcut',eval='qa.key(closingWindow,87,'+str(67108864)+')',wait='root.childWindows.length===3',assert_='report.visible && compare.visible')
    add('narrow title and report',eval='report.raise();report.requestActivate();report.width=640;report.height=480;',delay=100)
    add('narrow screenshot',delay=200,wait='report.active',assert_='qa.find(report,"memoryPlot").width>200',window='report',screenshot='report-narrow.png')
    add('open narrow category list',eval='qa.click(qa.find(report,"categoriesButton"),-1,-1)',wait='qa.find(report,"categoriesPopup").opened',window='report',screenshot='categories-open.png')
    add('toggle category',eval='var categoryPopup=qa.find(report,"categoriesPopup");qa.click(qa.find(categoryPopup,"category-GL"),-1,-1)',assert_='qa.find(report,"memoryChart").hidden.indexOf("GL")>=0',window='report',screenshot='narrow-categories.png')
    add('close categories',eval='qa.key(report,16777216)',wait='!qa.find(report,"categoriesPopup").opened')
    add('open chart display options',eval='qa.click(qa.find(report,"displayOptionsButton"),-1,-1)',wait='qa.find(report,"displayOptions").opened')
    add('adjust tooltip background opacity',eval='var opacity=qa.find(report,"tooltipOpacity");qa.click(opacity,opacity.width*.45,opacity.height/2);qa.click(qa.find(report,"pointsSwitch"),-1,-1)',assert_='qa.find(report,"memoryChart").tooltipAlpha<.7 && qa.find(report,"memoryChart").points',window='report',screenshot='chart-display-options.png')
    add('close display options',eval='qa.key(report,16777216)',wait='!qa.find(report,"displayOptions").opened')
    add('restore report width preserves categories',eval='report.width=1280;report.height=840;',assert_='qa.find(report,"memoryChart").hidden.indexOf("GL")>=0')
    add('environment information',eval='qa.click(qa.find(report,"environmentButton"),-1,-1)',wait='qa.find(report,"environmentDialog").opened',window='report',screenshot='environment.png')
    add('close environment',eval='qa.click(qa.find(qa.find(report,"environmentDialog"),"dialogClose"),-1,-1)',wait='!qa.find(report,"environmentDialog").opened')
    add('open rename dialog',eval='report.rename(report.meta.sessionDir,report.meta.taskName)',wait='qa.find(report,"renameDialog").opened',window='report',screenshot='rename.png')
    add('reject empty name',eval='qa.find(report,"renameField").text=""',assert_='!qa.find(qa.find(report,"renameDialog"),"dialogAccept").enabled')
    add('cancel rename',eval='qa.click(qa.find(qa.find(report,"renameDialog"),"dialogCancel"),-1,-1)',assert_='report.meta.taskName==="Trend-1"')
    add('open report library',eval='root.raise();root.requestActivate();root.go("reports")',wait='qa.find(root,"reportsTable")!==null')
    add('report actions stay visible while scrolling',eval='var library=qa.find(root,"reportsPage");var table=qa.find(root,"reportsTable");var tableScroll=qa.find(table,"tableScroll");tableScroll.contentX=150',assert_='Math.abs(qa.find(table,"header-actions").mapToItem(table,0,0).x+qa.find(table,"header-actions").width-table.width)<2')
    add('choose columns',eval='qa.click(qa.find(root,"columnsButton"),-1,-1)',wait='qa.find(root,"columnsPopup").opened')
    add('hide app column',eval='qa.click(qa.find(root,"column-bundleName"),-1,-1)',assert_='table.visibleColumns.every(c=>c.key!=="bundleName")')
    add('close columns',eval='qa.key(root,16777216)',wait='!qa.find(root,"columnsPopup").opened')
    add('mixed selection preserves rows',eval='library.selected=[' + 'backend.records.find(r=>r.id==="Trend-1").sessionDir,backend.records.find(r=>r.id==="Snapshot-1").sessionDir' + '];',assert_='library.mixed && library.selected.length===2 && !qa.find(root,"compareReportsButton").enabled',screenshot='reports-mixed-selection.png')
    add('valid selection enables compare',eval='library.selected=[' + 'backend.records.find(r=>r.id==="Trend-1").sessionDir,backend.records.find(r=>r.id==="Trend-2").sessionDir' + '];',assert_='qa.find(root,"compareReportsButton").enabled',screenshot='reports-selected.png')
    add('delete confirmation',eval='library.confirmDelete(library.selected)',wait='qa.find(root,"removeDialog").opened',screenshot='delete-confirmation.png')
    add('cancel deletion',eval='qa.click(qa.find(qa.find(root,"removeDialog"),"dialogCancel"),-1,-1)',assert_='library.selected.length===2')
    add('column preference survives navigation',eval='root.go("settings");root.go("reports")',wait='qa.find(root,"reportsTable")!==null',assert_='qa.find(root,"reportsTable").visibleColumns.every(c=>c.key!=="bundleName")')
    add('reset columns',eval='qa.find(root,"reportsTable").resetLayout()')
    add('minimum main window',eval='root.width=1024;root.height=680;root.go("peak")')
    add('advanced options at minimum size',delay=300,eval='qa.click(qa.find(root,"advancedOptions"),-1,-1)',assert_='qa.find(root,"toolPage").advanced && qa.find(root,"captureFooter").mapToItem(root.bodyItem,0,0).y+qa.find(root,"captureFooter").height<=root.bodyItem.height')
    add('minimum main screenshot',delay=300,screenshot='main-minimum.png')
    add('restore main size',eval='root.width=1280;root.height=820')
    add('open Windows Help',eval='if(root.windowsChrome) qa.click(qa.find(root,"helpButton"),-1,-1)',wait='!root.windowsChrome || qa.find(root,"helpMenu").opened')
    add('about dialog',eval='if(root.windowsChrome) {qa.key(root,16777237);qa.key(root,16777220);} else qa.find(root,"aboutDialog").open()',wait='qa.find(root,"aboutDialog").opened',screenshot='about.png')
    add('close about',eval='qa.click(qa.find(qa.find(root,"aboutDialog"),"dialogClose"),-1,-1)',wait='!qa.find(root,"aboutDialog").opened')
    if args.hdc:
        add('live configuration',eval='root.raise();root.requestActivate();root.go("watch");',wait='backend.target.length>0 && qa.find(root,"startButton") && qa.find(root,"startButton").enabled')
        add('start live via button',eval='qa.click(qa.find(root,"startButton"),-1,-1)',wait='root.page==="live" && backend.live.count>=2',timeout=10000)
        add('live window',screenshot='live.png',assert_='backend.live.stats.last===196608')
        add('quit confirmation retains active task',eval='backend.requestInteractiveQuit()',wait='qa.find(root,"quitDialog").opened',screenshot='quit-confirmation.png')
        add('continue active task',eval='qa.click(qa.find(qa.find(root,"quitDialog"),"dialogCancel"),-1,-1)',assert_='backend.sampling && root.page==="live"')
        add('stop live via button',eval='qa.click(qa.find(root,"stopButton"),-1,-1)',wait='!backend.sampling && root.page==="watch"')
    if args.hdc:
        add('application picker',eval='qa.click(qa.find(root,"appPicker"),-1,-1)',wait='qa.find(root,"appDialog").opened')
        add('search application by package',eval='qa.find(root,"appSearch").text="stopped"',assert_='qa.find(root,"appList").count===1',screenshot='app-picker.png')
        add('cancel pending app selection',eval='qa.click(qa.find(root,"app-com.example.stopped"),-1,-1);qa.click(qa.find(qa.find(root,"appDialog"),"dialogCancel"),-1,-1)',assert_='qa.find(root,"targetPicker").selectedBundle==="com.example.woodyqa"')
        add('device process exits',eval='qa.setFakeDeviceState({pid:0});backend.refreshApps()',wait='!qa.find(root,"targetPicker").selectedApp.pid')
        add('start waiting for app',eval='qa.click(qa.find(root,"startButton"),-1,-1)',wait='root.page==="live" && backend.live.count>=2',timeout=10000)
        add('waiting is not zero measurement',assert_='backend.live.stats.validCount===0 && qa.find(root,"statCards").values[0].value==="—"',screenshot='waiting-app.png')
        add('process restarts',eval='qa.setFakeDeviceState({pid:2412})',wait='backend.live.stats.validCount>=1',timeout=10000)
        add('waiting transitions to measured data',assert_='backend.live.stats.currentValid && backend.live.stats.last===196608 && qa.find(root,"statCards").values[0].value!=="—"')
        add('end restarted task',eval='qa.click(qa.find(root,"stopButton"),-1,-1)',wait='!backend.sampling && root.page==="watch"')
        add('prepare slow snapshot',eval='qa.setFakeDeviceState({pid:2411,delayMs:3000});root.go("snap");backend.refreshApps()',wait='qa.find(root,"startButton") && qa.find(root,"startButton").enabled')
        add('snapshot progress',eval='qa.click(qa.find(root,"startButton"),-1,-1)',wait='backend.snapshotting && qa.find(root,"snapshotProgress").opened')
        add('snapshot progress screenshot',delay=250,screenshot='snapshot-progress.png')
        add('cancel snapshot',eval='qa.click(qa.find(root,"cancelSnapshotButton"),-1,-1)',wait='!backend.snapshotting',timeout=2500)
        add('snapshot can retry',assert_='qa.find(root,"startButton").enabled && root.childWindows.length===3')
        add('invalid hdc settings',eval='root.go("settings");qa.find(root,"settingsPage").automatic=false;qa.find(root,"hdcPathField").text="/missing/woody-hdc"',assert_='!qa.find(root,"saveSettingsButton").enabled',screenshot='settings-invalid-path.png')
    for step in steps:
        if 'assert_' in step:step['assert']=step.pop('assert_')
    script=output/'scenario.json';script.write_text(json.dumps({'steps':steps},ensure_ascii=False,indent=2),encoding='utf-8')
    command=[str(args.exe.resolve()),'--profile',str(profile),'--qa',str(script),'--metrics',str(output/'startup.json')]
    if not args.hdc:command.append('--offline')
    env=os.environ.copy()
    if args.hdc:
        state=output/'hdc-state.json';state.write_text('{"pid":2411}',encoding='utf-8');env['WOODY_FAKE_STATE']=str(state)
    with (output/'application.log').open('w',encoding='utf-8') as log:
        result=subprocess.run(command,env=env,stdout=log,stderr=subprocess.STDOUT,timeout=180)
    log=(output/'application.log').read_text(encoding='utf-8',errors='replace');print(log)
    if result.returncode:
        if (output/'ui-result.json').exists():
            failed=json.loads((output/'ui-result.json').read_text(encoding='utf-8'));print(json.dumps(failed['steps'][-1],ensure_ascii=False));print('Evidence:',output)
        raise SystemExit(result.returncode)
    verification=json.loads((output/'ui-result.json').read_text(encoding='utf-8'))
    if not verification['passed']:raise SystemExit(2)
    if any(marker in log for marker in ['TypeError:','ReferenceError:','Unable to assign','Binding loop','failed to load component','Cannot specify','Row will not function','Error decoding','Only binding to one of multiple key bindings']):
        raise RuntimeError('QML runtime diagnostics found; see application.log')
    print('PASS',len(verification['steps']),'native UI checks')


if __name__=='__main__':main()
